// Read-only ordering subsets. Selectors are grounded in the dated public DOM.
import observed from '../fixtures/ordering-observed.json';
import { digits } from './m01';

export const ui = {
  quantity: 'main input[aria-label="تعداد بسته"]',
  increase: 'main button[aria-label="افزایش تعداد بسته"]',
  decrease: 'main button[aria-label="کاهش تعداد بسته"]',
  summary: 'main .summary-line-header',
  total: 'main .total-value',
  unit: 'main .summary-item--unit',
  perLabel: 'main .summary-item--label',
  mobileBar: 'main .product-mobile-bar',
  mobileLabels: 'main .mobile-bar-labels',
  mobileTotal: 'main .mobile-bar-total',
  form: '[data-cy="login-form"]',
  mobile: '#mobile'
};

export function text(value) {
  return digits(value).replace(/\s+/g, ' ').trim();
}

export function compact(value) {
  return digits(value).replace(/[\s٬,]/g, '');
}

export function observeQuotes() {
  cy.intercept('POST', observed.quotePath).as('quote');
}

export function productIdentity() {
  cy.location('pathname').should('eq', observed.product.path);
  cy.get('main h1').should('be.visible').and('have.text', observed.product.name);
  cy.get(ui.quantity).should('be.visible');
}

export function summary(quantity, labels) {
  cy.get(ui.quantity).should('have.value', String(quantity));
  cy.get(ui.summary).should('be.visible').should($el => {
    expect(text($el.text()), 'selected quantity/package and label arithmetic only')
      .eq(`${quantity} بستهٔ ${labels} لیبلی = ${quantity * labels} لیبل`);
  });
}

export function waitForQuote(quantity, pack = observed.packages.default) {
  cy.wait('@quote').then(({ request, response }) => {
    expect(request.body, 'observed read-only quote input').include({
      package_id: pack.id, quantity
    });
    expect(response, 'live quote completed').to.exist;
    expect(response.statusCode, 'quote readiness, not a pricing oracle').eq(200);
    expect(response.body, 'response identity matches selection').include({
      package_id: pack.id, quantity, labels_per_package: pack.labels
    });
    // Rendering readiness for this response, NOT an independent price oracle.
    // A label update alone can precede the monetary DOM update.
    replayPresentation(response.body);
  });
}

export function visitProduct() {
  observeQuotes();
  cy.visit(observed.product.path);
  productIdentity();
  waitForQuote(1);
}

export function selectedPackage(pack) {
  // No data-cy/aria-selected exists on package controls; this inspected state
  // class is a documented fallback, not a fabricated accessibility attribute.
  cy.contains('main button', pack.title).should('have.class', 'is-selected');
  cy.get('main .package-options-grid button.is-selected').should('have.length', 1);
}

export function currencyPresentation() {
  cy.get(ui.total).should('be.visible').should($el => {
    expect(compact($el.text()), 'numeric line amount with the displayed IRR unit')
      .match(/^\d+ریال$/);
  });
  cy.get(ui.unit).should('contain.text', 'ریال');
  cy.get(ui.perLabel).should('contain.text', 'ریال');
}

export function replayPresentation(quote) {
  // Only presentation of a supplied, captured response. These checks never
  // establish an independent price, tier, rounding, tax or financial oracle.
  summary(quote.quantity, quote.labels_per_package);
  cy.get(ui.total).should($el => {
    expect(compact($el.text()), 'replayed line-total presentation')
      .eq(`${quote.line_total_irr}ریال`);
  });
  cy.get(ui.unit).should($el => {
    expect(compact($el.text()), 'replayed unit presentation')
      .eq(`قیمتهربسته:${quote.unit_price_irr}ریال`);
  });
  cy.get(ui.perLabel).should($el => {
    expect(compact($el.text()), 'replayed per-label presentation')
      .eq(`هرلیبل:${quote.price_per_label_irr}ریال`);
  });
}

export function observeQuoteConsumption(win, records) {
  // Inspection confirmed native fetch + response.json() for this quote. Wrap
  // only response consumption; preserve the response bytes and native promises.
  const nativeFetch = win.fetch.bind(win);
  win.fetch = (...args) => {
    let input;
    try { input = JSON.parse(args[1]?.body); } catch { /* No synthetic request metadata. */ }
    return nativeFetch(...args).then(response => {
      if (new URL(response.url, win.location.origin).pathname !== observed.quotePath) return response;
      for (const method of ['text', 'json']) {
        const read = response[method].bind(response);
        response[method] = (...params) => read(...params).then(value => {
          const body = method === 'json' ? value : JSON.parse(value);
          records.push({ event: 'consumed', quantity: body.quantity, packageId: body.package_id, method });
          return value;
        }, error => {
          records.push({ event: 'read-error', quantity: input?.quantity, packageId: input?.package_id, errorName: error.name });
          throw error; // Preserve native rejection; the application owns error handling.
        });
      }
      return response;
    });
  };
}

export function afterBrowserRender() {
  // Two actual rendering opportunities after body consumption let native
  // promise continuations and the observed Vue render cycle finish. No timer,
  // app-internal hook or fixed latency assumption is used.
  cy.window().then(win => new Cypress.Promise(resolve => {
    win.requestAnimationFrame(() => win.requestAnimationFrame(() => resolve()));
  }));
}
